 11→function getLastThinkingLine(segments: ContentSegment[], streamingRemainder: string | undefined, t: (key: string) => string): string {
 12→  // Use streaming remainder if available
 13→  if (streamingRemainder?.trim()) {
 14→    const lines = streamingRemainder.trim().split('\n').filter((l) => l.trim());
 15→    const last = lines[lines.length - 1] || '';
 16→    return last.length > 100 ? last.slice(0, 100) + '...' : last;
 17→  }
 18→  // Otherwise use last thinking segment's last line
 19→  for (let i = segments.length - 1; i >= 0; i--) {
 20→    if (segments[i].type === 'thinking' && segments[i].text?.trim()) {
 21→      const lines = segments[i].text!.trim().split('\n').filter((l) => l.trim());
 22→      const last = lines[lines.length - 1] || '';
 23→      return last.length > 100 ? last.slice(0, 100) + '...' : last;
 24→    }
 25→  }
 26→  return t('thinking');
 27→}
 28→
 29→function ThinkingBlock({ segments, streamingRemainder, isThinkingPhase, isAgentStreaming }: {
 30→  segments: ContentSegment[];
 31→  streamingRemainder?: string;
 32→  isThinkingPhase: boolean;
 33→  isAgentStreaming: boolean;
 34→}) {
 35→  const { t } = useTranslation();
 36→  // All non-answer, non-chart segments go inside the thinking block
 37→  const thinkingSegments = segments.filter(
 38→    (s) => s.type !== 'answer' && !(s.type === 'tool' && s.toolResult?.chart_spec) && !(s.type === 'subagent_end' && s.chart_spec)
 39→  );
 40→  const hasContent = thinkingSegments.some(
 41→    (s) => (s.type === 'thinking' && s.text?.trim()) || (s.type === 'tool' && s.toolResult) || s.type === 'subagent_start'
 42→  ) || streamingRemainder?.trim();
 43→
 44→  if (!hasContent) return null;
 45→
 46→  // Show preview only while agent is still working (hidden by CSS when collapsible is open anyway)
 47→  const summary = isAgentStreaming ? getLastThinkingLine(segments, streamingRemainder, t) : '';
 48→
 49→  return (
 50→    <details className="message-bubble__segment message-bubble__segment--thinking message-bubble__collapsible" open={isThinkingPhase || undefined}>
 51→      <summary className="message-bubble__collapsible-summary">
 52→        <span className="message-bubble__segment-label">{t('thinkingLabel')}</span>
 53→        {summary && <span className="message-bubble__collapsible-preview">{summary}</span>}
 54→      </summary>
 55→      <div className="message-bubble__thinking-body">
 56→        {thinkingSegments.map((seg, i) => {
 57→          if (seg.type === 'thinking' && seg.text?.trim()) {
 58→            return (
 59→              <div key={i} className="message-bubble__segment-content">
 60→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text}</ReactMarkdown>
 61→              </div>
 62→            );
 63→          }
 64→          if (seg.type === 'tool' && seg.toolResult) {
 65→            return (
 66→              <div key={i} className="message-bubble__tool-segment">
 67→                <InlineQueryResult result={seg.toolResult} />
 68→              </div>
 69→            );
 70→          }
 71→          if (seg.type === 'subagent_start') {
 72→            const displayName = seg.subagentName === 'sql-analyst'
 73→              ? 'SQL Analyst working...'
 74→              : seg.subagentName === 'chart-builder'
 75→              ? 'Chart Builder working...'
 76→              : `${seg.subagentName} working...`;
 77→            return (
 78→              <div key={i} className="message-bubble__subagent-indicator">
 79→                <span className="message-bubble__subagent-label">{displayName}</span>
 80→              </div>
 81→            );
 82→          }
 83→          return null;
 84→        })}
 85→        {streamingRemainder?.trim() && (
 86→          <div className="message-bubble__segment-content">
 87→            <ReactMarkdown remarkPlugins={[remarkGfm]}>{streamingRemainder}</ReactMarkdown>
 88→          </div>
 89→        )}
 90→      </div>
 91→    </details>
 92→  );
 93→}
