 95→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
 96→  const { t } = useTranslation();
 97→  const { isStreaming, editMessage, deleteMessage } = useAgent();
 98→  const [isEditing, setIsEditing] = useState(false);
 99→  const [editText, setEditText] = useState(message.content);
100→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
101→  const textareaRef = useRef<HTMLTextAreaElement>(null);
102→
103→  const isUser = message.role === 'user';
104→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
105→
106→  useEffect(() => {
107→    if (isEditing && textareaRef.current) {
108→      textareaRef.current.focus();
109→      textareaRef.current.selectionStart = textareaRef.current.value.length;
110→    }
111→  }, [isEditing]);
112→
113→  const handleEdit = () => {
114→    setEditText(message.content);
115→    setIsEditing(true);
116→    setIsConfirmingDelete(false);
117→  };
118→
119→  const handleCancelEdit = () => {
120→    setIsEditing(false);
121→    setEditText(message.content);
122→  };
123→
124→  const handleSaveEdit = () => {
125→    const trimmed = editText.trim();
126→    if (!trimmed || trimmed === message.content) {
127→      handleCancelEdit();
128→      return;
129→    }
130→    setIsEditing(false);
131→    editMessage(messageIndex, trimmed);
132→  };
133→
134→  const handleDeleteConfirm = () => {
135→    setIsConfirmingDelete(false);
136→    deleteMessage(messageIndex);
137→  };
138→
139→  const handleKeyDown = (e: React.KeyboardEvent) => {
140→    if (e.key === 'Escape') {
141→      handleCancelEdit();
142→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
143→      e.preventDefault();
144→      handleSaveEdit();
145→    }
146→  };
147→
148→  let streamingRemainder: string | undefined;
149→  if (hasSegments && message.isStreaming && message.content) {
150→    const segmentedText = message.segments!
151→      .filter((s) => s.type !== 'tool')
152→      .map((s) => s.text || '')
153→      .join('');
154→    const remaining = message.content.slice(segmentedText.length);
155→    if (remaining.trim()) {
156→      streamingRemainder = remaining;
157→    }
158→  }
159→
160→  const hasAnswer = hasSegments && message.segments!.some((s) => s.type === 'answer');
161→  const isInAnswerPhase = message.currentPhase === 'answer';
162→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
163→
164→  const answerSegments = hasSegments
165→    ? message.segments!.filter((s) => s.type === 'answer' && s.text?.trim())
166→    : [];
167→
168→  const chartSegments = hasSegments
169→    ? message.segments!.filter(
170→        (s) =>
171→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
172→          (s.type === 'subagent_end' && s.chart_spec)
173→      )
174→    : [];
175→
176→  return (
177→    <div className={`message-bubble message-bubble--${message.role}`}>
178→      <div className="message-bubble__header">
179→        {isUser ? t('you') : t('assistant')}
180→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
181→          <span className="message-bubble__actions">
182→            <button
183→              className="message-bubble__action-btn"
184→              onClick={handleEdit}
185→              title={t('editMessage')}
186→            >
187→              &#9998;
188→            </button>
189→            <button
190→              className="message-bubble__action-btn message-bubble__action-btn--delete"
191→              onClick={() => setIsConfirmingDelete(true)}
192→              title={t('deleteMessage')}
193→            >
194→              &#128465;
195→            </button>
196→          </span>
197→        )}
198→      </div>
199→
200→      {isUser && isConfirmingDelete && (
201→        <div className="message-bubble__confirm-delete">
202→          <span>{t('deleteConfirm')}</span>
203→          <div className="message-bubble__confirm-actions">
204→            <button
205→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
206→              onClick={handleDeleteConfirm}
207→            >
208→              {t('delete')}
209→            </button>
210→            <button
211→              className="message-bubble__confirm-btn"
212→              onClick={() => setIsConfirmingDelete(false)}
213→            >
214→              {t('cancel')}
215→            </button>
216→          </div>
217→        </div>
218→      )}
219→
220→      {isUser && isEditing ? (
221→        <div className="message-bubble__edit-mode">
222→          <textarea
223→            ref={textareaRef}
224→            className="message-bubble__edit-textarea"
225→            value={editText}
226→            onChange={(e) => setEditText(e.target.value)}
227→            onKeyDown={handleKeyDown}
228→            rows={3}
229→          />
230→          <div className="message-bubble__edit-actions">
231→            <button
232→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
233→              onClick={handleSaveEdit}
234→            >
235→              {t('saveResend')}
236→            </button>
237→            <button
238→              className="message-bubble__edit-btn"
239→              onClick={handleCancelEdit}
240→            >
241→              {t('cancel')}
242→            </button>
243→          </div>
244→        </div>
245→      ) : hasSegments ? (
246→        <div className="message-bubble__segments">
247→          <ThinkingBlock
248→            segments={message.segments!}
249→            streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
250→            isThinkingPhase={isThinkingPhase}
251→            isAgentStreaming={!!message.isStreaming}
252→          />
253→          {chartSegments.map((seg, i) => (
254→            <div key={`chart-${i}`} className="message-bubble__segment message-bubble__segment--answer">
255→              {seg.type === 'tool' && seg.toolResult ? (
256→                <InlineQueryResult result={seg.toolResult!} />
257→              ) : seg.chart_spec ? (
258→                <ChartWidget data={seg.chart_spec.data} layout={seg.chart_spec.layout} />
259→              ) : null}
260→            </div>
261→          ))}
262→          {answerSegments.map((seg, i) => (
263→            <div key={i} className="message-bubble__segment message-bubble__segment--answer">
264→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
265→              <div className="message-bubble__segment-content">
266→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
267→              </div>
268→            </div>
269→          ))}
270→          {isInAnswerPhase && !hasAnswer && streamingRemainder?.trim() && (
271→            <div className="message-bubble__segment message-bubble__segment--answer">
272→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
273→              <div className="message-bubble__segment-content">
274→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{streamingRemainder}</ReactMarkdown>
275→              </div>
276→            </div>
277→          )}
278→          {message.isStreaming && !message.content && (
279→            <span className="message-bubble__typing">{t('thinking')}</span>
280→          )}
281→        </div>
282→      ) : (
283→        <>
284→          <div className="message-bubble__content">
285→            {message.content ? (
286→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
287→            ) : message.isStreaming ? (
288→              <span className="message-bubble__typing">{t('thinking')}</span>
289→            ) : null}
290→          </div>
291→          {message.toolCalls && message.toolCalls.length > 0 && (
292→            <div className="message-bubble__tools">
293→              {message.toolCalls.map((tc) => (
294→                <InlineQueryResult key={tc.toolCallId} result={tc} />
295→              ))}
296→            </div>
297→          )}
298→        </>
299→      )}
300→    </div>
301→  );
302→}
